#include <assert.h>
#include "protocol.h"
int main(void){unsigned char b[12]={1,1,0,0,1,0,0,0,'{','}',0,0};struct cl_request r;unsigned i;assert(cl_parse_request(b,10,0,&r));assert(r.opcode==1&&r.id==1&&r.bytes==2&&r.body==b+8);assert(!cl_parse_request(b,10,1,&r));assert(!cl_parse_request(b,7,0,&r));assert(!cl_parse_request(b,65537,0,&r));for(i=0;i<4;i++){unsigned char saved=b[i];b[i]=i==0?2:i==1?8:1;assert(!cl_parse_request(b,10,0,&r));b[i]=saved;}b[1]=2;assert(cl_parse_request(b,10,0,&r));b[1]=3;assert(cl_parse_request(b,10,0,&r));b[1]=4;assert(cl_parse_request(b,10,0,&r));b[1]=5;assert(cl_parse_request(b,10,0,&r));b[1]=6;assert(cl_parse_request(b,10,0,&r));b[1]=7;assert(cl_parse_request(b,10,0,&r));return 0;}
